// Builds the Microsoft Graph request for the office mailbox / calendar.
const inp = $input.first().json || {};
const action = String(inp.action || '');
let a = {};
try { a = typeof inp.args === 'string' ? (inp.args ? JSON.parse(inp.args) : {}) : (inp.args || {}); } catch (e) { return [{ json: { error: 'args must be valid JSON', skip: true } }]; }
const TZ = 'Arab Standard Time';
const enc = encodeURIComponent;
const id = String(a.id || a.message_id || a.event_id || '').trim();
function need(v, name) { if (!v) throw new Error('missing ' + name); }
function rcpts(s) { return String(s || '').split(/[,;]/).map(function (x) { return x.trim(); }).filter(Boolean).map(function (x) { return { emailAddress: { address: x } }; }); }
const SEL = 'id,conversationId,subject,from,receivedDateTime,bodyPreview,isRead,importance,hasAttachments,webLink';
let r;
try {
  switch (action) {
    case 'search_mail': {
      const top = Math.min(Math.max(parseInt(a.limit || 10, 10) || 10, 1), 25);
      if (a.query) r = { method: 'GET', url: '/me/messages?$search=' + enc('"' + String(a.query).replace(/"/g, '') + '"') + '&$top=' + top + '&$select=' + SEL };
      else {
        const f = [];
        if (a.days) f.push('receivedDateTime ge ' + new Date(Date.now() - Number(a.days) * 86400000).toISOString());
        if (a.unread_only) f.push('isRead eq false');
        r = { method: 'GET', url: '/me/mailFolders/inbox/messages?$top=' + top + '&$orderby=receivedDateTime desc&$select=' + SEL + (f.length ? '&$filter=' + enc(f.join(' and ')) : '') };
      }
      break; }
    case 'read_mail': need(id, 'id'); r = { method: 'GET', url: '/me/messages/' + enc(id) + '?$select=' + SEL + ',toRecipients,ccRecipients,body' }; break;
    case 'draft_reply': need(id, 'id'); r = { method: 'POST', url: '/me/messages/' + enc(id) + '/createReply', body: { comment: String(a.body || '') } }; break;
    case 'reply': need(id, 'id'); need(a.body, 'body'); r = { method: 'POST', url: '/me/messages/' + enc(id) + '/reply', body: { comment: String(a.body) } }; break;
    case 'create_draft': r = { method: 'POST', url: '/me/messages', body: { subject: String(a.subject || ''), body: { contentType: 'Text', content: String(a.body || '') }, toRecipients: rcpts(a.to) } }; break;
    case 'send_mail': need(a.to, 'to'); need(a.subject, 'subject'); r = { method: 'POST', url: '/me/sendMail', body: { message: { subject: String(a.subject), body: { contentType: 'Text', content: String(a.body || '') }, toRecipients: rcpts(a.to), ccRecipients: rcpts(a.cc) }, saveToSentItems: true } }; break;
    case 'archive': need(id, 'id'); r = { method: 'POST', url: '/me/messages/' + enc(id) + '/move', body: { destinationId: 'archive' } }; break;
    case 'mark_read': need(id, 'id'); r = { method: 'PATCH', url: '/me/messages/' + enc(id), body: { isRead: true } }; break;
    case 'list_events': {
      const days = Math.min(Math.max(parseInt(a.days || 14, 10) || 14, 1), 90);
      const start = a.start ? new Date(a.start) : new Date(Date.now() - 3600000);
      const end = new Date(start.getTime() + days * 86400000);
      r = { method: 'GET', url: '/me/calendarView?startDateTime=' + enc(start.toISOString()) + '&endDateTime=' + enc(end.toISOString()) + '&$orderby=start/dateTime&$top=60&$select=id,subject,start,end,location,bodyPreview,isAllDay,webLink' };
      break; }
    case 'create_event': {
      need(a.subject, 'subject'); need(a.start, 'start');
      const ev = { subject: String(a.subject), start: { dateTime: String(a.start), timeZone: TZ }, end: { dateTime: String(a.end || a.start), timeZone: TZ }, isReminderOn: true, reminderMinutesBeforeStart: parseInt(a.reminder_minutes || 30, 10) || 30 };
      if (!a.end) { const s = new Date(String(a.start) + 'Z'); ev.end.dateTime = new Date(s.getTime() + (parseInt(a.duration_minutes || 60, 10) || 60) * 60000).toISOString().slice(0, 19); }
      if (a.all_day) ev.isAllDay = true;
      if (a.location) ev.location = { displayName: String(a.location) };
      if (a.notes) ev.body = { contentType: 'Text', content: String(a.notes) };
      if (a.attendees) ev.attendees = rcpts(a.attendees).map(function (x) { return { emailAddress: x.emailAddress, type: 'required' }; });
      r = { method: 'POST', url: '/me/events', body: ev }; break; }
    case 'update_event': {
      need(id, 'id'); const ev = {};
      if (a.subject) ev.subject = String(a.subject);
      if (a.start) ev.start = { dateTime: String(a.start), timeZone: TZ };
      if (a.end) ev.end = { dateTime: String(a.end), timeZone: TZ };
      if (a.location) ev.location = { displayName: String(a.location) };
      if (a.notes) ev.body = { contentType: 'Text', content: String(a.notes) };
      r = { method: 'PATCH', url: '/me/events/' + enc(id), body: ev }; break; }
    case 'delete_event': need(id, 'id'); r = { method: 'DELETE', url: '/me/events/' + enc(id) }; break;
    default: return [{ json: { error: 'unknown action ' + action, skip: true } }];
  }
} catch (e) { return [{ json: { error: e.message, skip: true } }]; }
return [{ json: { skip: false, action: action, method: r.method, url: 'https://graph.microsoft.com/v1.0' + r.url, hasBody: !!r.body, body: JSON.stringify(r.body || {}) } }];

const b = $('Build Graph Request').first().json;
if (b.skip) return [{ json: { ok: false, error: b.error } }];
const res = $input.first().json || {};
const code = res.statusCode || 200;
const data = res.body !== undefined ? res.body : res;
if (code >= 400) { const msg = (data && data.error && data.error.message) || ('HTTP ' + code); return [{ json: { ok: false, error: msg } }]; }
function who(x) { const e = x && x.emailAddress; return e ? ((e.name ? e.name + ' ' : '') + '<' + e.address + '>') : ''; }
function strip(h) { return String(h || '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim(); }
function mail(m) { return { id: m.id, conversationId: m.conversationId, from: who(m.from), subject: m.subject || '', received: m.receivedDateTime || '', preview: (m.bodyPreview || '').slice(0, 200), isRead: m.isRead, importance: m.importance, hasAttachments: m.hasAttachments }; }
function when(x) { return x ? String(x.dateTime || '').slice(0, 16).replace('T', ' ') : ''; }
function ev(e) { return { id: e.id, subject: e.subject || '', start: when(e.start), end: when(e.end), allDay: !!e.isAllDay, location: (e.location && e.location.displayName) || '', notes: (e.bodyPreview || '').slice(0, 200) }; }
switch (b.action) {
  case 'search_mail': return [{ json: { ok: true, messages: ((data && data.value) || []).map(mail) } }];
  case 'read_mail': { let t = data.body && data.body.contentType === 'html' ? strip(data.body.content) : String((data.body && data.body.content) || ''); const tr = t.length > 4000; return [{ json: { ok: true, message: Object.assign(mail(data), { to: (data.toRecipients || []).map(who).join(', '), cc: (data.ccRecipients || []).map(who).join(', '), body: t.slice(0, 4000), truncated: tr }) } }]; }
  case 'list_events': return [{ json: { ok: true, timezone: 'Bahrain (UTC+3)', events: ((data && data.value) || []).map(ev) } }];
  case 'create_event': case 'update_event': return [{ json: { ok: true, event: ev(data) } }];
  case 'draft_reply': case 'create_draft': return [{ json: { ok: true, draft_id: data.id, note: 'Draft saved in Outlook Drafts, not sent' } }];
  default: return [{ json: { ok: true, done: b.action } }];
}

